message E2SubscriptionApiPayload { oneof procedure_type { E2SubscriptionProc e2_subscription_proc $\ c = \ 1$ ; E2SubscriptionDeleteProc e2_subscription_delete_proc $= ~ 2$ ; E2SubscriptionDeleteQueryProc e2_subscription_delete_query_proc $\qquad = \ 3$ ; E2SubscriptionDeleteNotificationProc e2_subscription_delete_notification_proc $= ~ 4$ ; }   
}   
// ---- procedures of E2_Subscription_API   
message E2SubscriptionProc { oneof type_of_message { E2SubscriptionRequest e2_subscription_request $\ c = \ 1$ ; E2SubscriptionSuccess e2_subscription_success $= ~ 2$ ; E2SubscriptionReject e2_subscription_reject $=$ 3 ; E2SubscriptionFailure e2_subscription_failure $= ~ 4$ ; }   
}

E2SubscriptionDeleteRequest e2_subscription_delete_request $\ c = \ 1$ ; E2SubscriptionDeleteSuccess e2_subscription_delete_success $= ~ 2$ ; E2SubscriptionDeleteReject e2_subscription_delete_reject $=$ 3 ; E2SubscriptionDeleteFailure e2_subscription_delete_failure $= 4$ ; } }

