}   
message E2SubscriptionDeleteNotificationProc { oneof type_of_message { E2SubscriptionDeleteNotificationDeleted e2_subscription_delete_notification_deleted $\ c = \ 1$ ; }   
}   
// --- messages of E2_Subscription_API   
// messages of E2 Subscription procedure   
message E2SubscriptionRequest { optional near_rt_ric_apis_common_ies.v2.ProcedureTransactionId procedure_transaction_id $\ c = \ 1$ ; optional near_rt_ric_apis_common_ies.v2.GlobalE2NodeId global_e2_node_id $= ~ 2$ ; optional near_rt_ric_apis_common_ies.v2.RanFunctionId ran_function_id $\qquad = \ 3$ ; optional E2SubscriptionDetails e2_subscription_details $= ~ 4$ ; optional uint32 e2_subscription_timer $= ~ 5$ ; optional near_rt_ric_apis_common_ies.v2.EndpointInformation e2_indication_destination $= ~ 6$ ; optional near_rt_ric_apis_common_ies.v2.EndpointInformation   
e2_subscription_delete_notification_destination $= ~ 7$ ;

message E2SubscriptionDetails { optional e2_related_apis_common_ies.v1.E2EventTriggerDefinition e2_event_trigger_definition $\ c = \ 1$ repeated E2ActionToBeSetupItem sequence_of_actions $= ~ 2$ ;

message E2ActionToBeSetupItem $\begin{array} { r } { \mathopen { } \mathclose \bgroup \left\{ \begin{array} { r l r l } \end{array} \aftergroup \egroup \right. } \end{array}$ optional e2_related_apis_common_ies.v1.E2ActionId requested_e2_action_id $\ c = \texttt { 1 }$ ; optional e2_related_apis_common_ies.v1.E2ActionType e2_action_type $= ~ 2$ ; optional e2_related_apis_common_ies.v1.E2ActionDefinition e2_action_definition $\qquad = \ 3$ optional e2_related_apis_common_ies.v1.E2SubsequentAction e2_subsequent_action $= 4$ } } }

message E2SubscriptionSuccess { optional near_rt_ric_apis_common_ies.v2.ProcedureTransactionId procedure_transaction_id $\ c = \ 1$ ; optional near_rt_ric_apis_common_ies.v2.GlobalE2NodeId global_e2_node_id $= ~ 2$ ; optional e2_related_apis_common_ies.v1.E2RequestId e2_request_id $\qquad = \ 3$ ; optional near_rt_ric_apis_common_ies.v2.RanFunctionId ran_function_id $= ~ 4$ ; repeated E2ActionAdmittedItem e2_actions_admitted_list $= ~ 5$ ; repeated E2ActionNotAdmittedItem e2_actions_not_admitted_list $= ~ 6$ ;

