syntax $=$ "proto3";

package ricapi.near_rt_ric_apis_common_ies.v2;

// Information elements used across different API categories

// Information Elements // A  
// From A1TD Clause 5.2   
message A1PolicyTypeId {   
optional string value $\ c = \ 1$ ;   
}

enum ApiName { APINAME_E2_SUBSCRIPTION_API $\mathit { \Theta } = \mathit { \Theta } \Theta$ ; APINAME_E2_INDICATION_API $\ c = \ 1$ ; APINAME_E2_CONTROL_API $= ~ 2$ ; APINAME_E2_GUIDANCE_API $\qquad = \ 3$ ; APINAME_A1_POLICY_API $= ~ 4$ ; APINAME_A1_EI_API $= ~ 5$ ; APINAME_SDL_INFORMATION_API $= ~ 6$ ; APINAME_XAPP_DATA_SHARING_API $= ~ 7$ ;

// BitString definition   
message BitString { optional bytes value $\ c = \ 1$ ; optional uint32 len $= ~ 2$ ;   
}   
// - ---   
message EndpointInformation $\begin{array} { r } { \mathopen { } \mathclose \bgroup \left\{ \begin{array} { r l r l } \end{array} \aftergroup \egroup \right. } \end{array}$ optional string domain_name $\ c = \ 1$ ; optional string ipv4_address $= ~ 2$ ; optional string ipv6_address $\qquad = \ 3$ ; optional uint32 port $= 4$ ;   
}; // ---   
// From E2AP Clause 9.2.6, "Global E2 Node ID"   
message GlobalE2NodeId { oneof node_type { GlobalE2NodeGnbId gnb $\ c = \ 1$ ; GlobalE2NodeEnGnbId en_gnb $= ~ 2$ ; GlobalE2NodeNgEnbId ng_enb $\qquad = \ 3$ ; GlobalE2NodeEnbId enb $= ~ 4$ ; }   
message GlobalE2NodeGnbId { optional GlobalGnbId global_gnb_id $\ c = \ 1$ ; optional GlobalEnGnbId global_en_gnb_id $= ~ 2$ ; optional GnbCuUpId gnb_cu_up_id $\qquad = \ 3$ ; optional GnbDuId gnb_du_id $= ~ 4$ ;   
}

optional GnbCuUpId en_gnb_cu_up_id $= ~ 2$ ; optional GnbDuId en_gnb_du_id $\qquad = \ 3$ ; } message GlobalE2NodeNgEnbId { optional GlobalNgEnbId global_ng_enb_id = 1; optional GlobalEnbId global_enb_id $= ~ 2$ ; optional NgEnbDuId ng_enb_du_id $\qquad = \ 3$ ; } message GlobalE2NodeEnbId { optional GlobalEnbId global_enb_id $\ c = \ 1$ ; }

// From E2AP Clause 9.2.6, as part of "Global E2 Node ID"   
message GlobalEnbId { optional PlmnIdentity plmn_identity $\ c = \texttt { 1 }$ ; oneof enb_id_choice BitString macro_enb_id $= ~ 2$ ; BitString home_enb_id $\ c = \ 3 \ r _ { i }$ ; BitString short_macro_enb_id $= ~ 4$ ; BitString long_macro_enb_id $= 5$ ; }   
}   
// From E2AP Clause 9.2.6, as part of "Global E2 Node ID"   
message GlobalEnGnbId { optional PlmnIdentity plmn_identity $\ c = \texttt { 1 }$ ; oneof en_gnb_id_choice { BitString en_gnb_id $= ~ 2$ ; }   
}   
// From E2AP Clause 9.2.6, as part of "Global E2 Node ID"   
message GlobalGnbId { optional PlmnIdentity plmn_identity $\ c = \texttt { 1 }$ ; oneof gnb_id_choice { BitString gnb_id $= ~ 2$ ; }   
}   
// From E2AP Clause 9.2.6, as part of "Global E2 Node ID"   
message GlobalNgEnbId $\begin{array} { r } { \mathopen { } \mathclose \bgroup \left\{ \begin{array} { r l r l } \end{array} \aftergroup \egroup \right. } \end{array}$ optional PlmnIdentity plmn_identity $\ c = \ 1$ ; oneof ng_enb_id_choice { BitString macro_ng_enb_id $= ~ 2$ ; BitString short_macro_ng_enb_id $\qquad = \ 3$ ; BitString long_macro_ng_enb_id $= ~ 4$ ; }   
}   
// From E2AP Clause 9.2.6, as part of "Global E2 Node ID"   
message GnbCuUpId $\begin{array} { r } { \mathopen { } \mathclose \bgroup \left\{ \begin{array} { r l r l } \end{array} \aftergroup \egroup \right. } \end{array}$ optional uint64 value $\ c = \ 1$ ;   
}   
// From E2AP Clause 9.2.6, as part of "Global E2 Node ID"   
message GnbDuId { optional uint64 value $\ c = \ 1$ ;   
}   
//   
// From E2AP Clause 9.2.8, "RAN Function ID"   
message RanFunctionId { optional uint32 value $\ c = \ 1$ ;   
};   
//-   
// Outer layer encapsulation for SCTP based APIs   
message SctpApiPdu { optional ApiName api_name $\ c = \texttt { 1 }$ ; optional ApiVersion api_version $= ~ 2$ ; optional bytes api_payload $\qquad = \ 3$ ;   
}   
//   
message XappId { optional string value $\ c = \ 1$ ;   
}

